import{_ as t,o as a,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/commands.md","filePath":"modules/item/commands.md","lastUpdated":null}'),o={name:"modules/item/commands.md"};function s(c,e,n,l,p,r){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to &quot;命令与权限&quot;">​</a></h1><p>EmakiItem 的主命令是 <code>/emakiitem</code>，别名 <code>/ei</code>。命令用于列出物品、发放物品、检查手持物、查看 Minecraft 物品组件、刷新玩家物品和套装状态、重载配置与输出调试信息。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to &quot;命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/ei help</code></td><td>无</td><td>输出命令帮助。不带参数执行 <code>/ei</code> 等价于 <code>help</code>。</td></tr><tr><td><code>/ei list [page]</code></td><td><code>emakiitem.use</code></td><td>分页列出已加载的物品定义，每页 10 条。</td></tr><tr><td><code>/ei give &lt;player&gt; &lt;id&gt; [amount]</code></td><td><code>emakiitem.give</code></td><td>给指定玩家发放 EmakiItem 物品。</td></tr><tr><td><code>/ei inspect [player]</code></td><td><code>emakiitem.inspect</code></td><td>检查指定玩家或自己的主手物品，输出物品 ID、版本、属性、技能、套装等 PDC 状态。</td></tr><tr><td><code>/ei components [yaml] [player] [component_id]</code></td><td><code>emakiitem.inspect</code></td><td>查看主手物品的 Minecraft 组件；默认保持 JSON，只有显式写 <code>yaml</code> 时输出可复制到 <code>item.components</code> 的 YAML。也可用 <code>/ei component</code>。</td></tr><tr><td><code>/ei repair</code></td><td><code>emakiitem.use</code></td><td>为自己打开装备修复界面，仅玩家可用。</td></tr><tr><td><code>/ei update [player]</code></td><td><code>emakiitem.update</code></td><td>刷新玩家背包中的 EmakiItem 物品，并重新计算套装状态。</td></tr><tr><td><code>/ei alias list|add|remove</code></td><td><code>emakiitem.admin</code></td><td>查看、添加或删除物品 ID alias。</td></tr><tr><td><code>/ei migrate id|inventory</code></td><td><code>emakiitem.admin</code></td><td>预览或执行物品 ID 迁移，或迁移玩家背包。</td></tr><tr><td><code>/ei reload</code></td><td><code>emakiitem.reload</code></td><td>重载物品、套装、配置和语言。</td></tr><tr><td><code>/ei debug [stats|player|module|on|off]</code></td><td><code>emakiitem.debug</code> 或 <code>emakiitem.admin</code></td><td>输出运行时调试信息；<code>stats</code> 输出刷新统计。</td></tr></tbody></table><h2 id="权限节点" tabindex="-1">权限节点 <a class="header-anchor" href="#权限节点" aria-label="Permalink to &quot;权限节点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakiitem.use</code></td><td>true</td><td>使用基础命令和物品列表。</td></tr><tr><td><code>emakiitem.give</code></td><td>op</td><td>发放自定义物品。</td></tr><tr><td><code>emakiitem.inspect</code></td><td>op</td><td>检查物品状态和 Minecraft 组件。</td></tr><tr><td><code>emakiitem.update</code></td><td>op</td><td>刷新玩家物品或套装状态。</td></tr><tr><td><code>emakiitem.reload</code></td><td>op</td><td>重载配置。</td></tr><tr><td><code>emakiitem.debug</code></td><td>op</td><td>输出调试信息。</td></tr><tr><td><code>emakiitem.admin</code></td><td>op</td><td>管理 alias 与迁移命令，同时作为调试命令的管理员兜底权限。</td></tr></tbody></table><p>主命令 <code>/emakiitem</code> 本身要求 <code>emakiitem.use</code>；<code>repair</code> 子命令也使用该权限。</p><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to &quot;常见操作&quot;">​</a></h2><h3 id="查看物品列表" tabindex="-1">查看物品列表 <a class="header-anchor" href="#查看物品列表" aria-label="Permalink to &quot;查看物品列表&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei list</span></span>
<span class="line"><span>/ei list 2</span></span></code></pre></div><p>用于确认 <code>plugins/EmakiItem/items/</code> 目录中的物品是否成功加载。列表会显示配置 ID 和显示名。</p><h3 id="发放物品" tabindex="-1">发放物品 <a class="header-anchor" href="#发放物品" aria-label="Permalink to &quot;发放物品&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei give Steve example_item 1</span></span></code></pre></div><p>发放后模块会执行该物品的 <code>actions.give</code>，刷新玩家已有 EmakiItem 物品、套装状态，并触发 Attribute 装备同步。发放失败时先确认物品 ID 是否存在。</p><h3 id="检查主手物品" tabindex="-1">检查主手物品 <a class="header-anchor" href="#检查主手物品" aria-label="Permalink to &quot;检查主手物品&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei inspect</span></span>
<span class="line"><span>/ei inspect Steve</span></span></code></pre></div><p><code>inspect</code> 会读取目标玩家主手物品，并输出：</p><ul><li>EmakiItem ID；</li><li>schema / update 版本；</li><li>物品定义是否仍存在；</li><li><code>emakiitem</code> 命名空间写入的 Attribute PDC（<code>attributes</code> 与 <code>attribute_meta</code>）；</li><li>技能 ID 与装备强制技能触发器；</li><li>definition signature；</li><li>套装 ID、部件、当前激活数量、总件数和已激活阈值。</li></ul><p>排查“属性没生效”“套装不触发”“技能没出现”时，优先看这里，而不是只看 Lore。</p><h3 id="查看-minecraft-物品组件" tabindex="-1">查看 Minecraft 物品组件 <a class="header-anchor" href="#查看-minecraft-物品组件" aria-label="Permalink to &quot;查看 Minecraft 物品组件&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei components</span></span>
<span class="line"><span>/ei components Steve</span></span>
<span class="line"><span>/ei components Steve custom_model_data</span></span>
<span class="line"><span>/ei components yaml</span></span>
<span class="line"><span>/ei components yaml Steve custom_model_data</span></span>
<span class="line"><span>/ei component custom_model_data</span></span></code></pre></div><p><code>components</code> 无格式参数时保持既有 JSON 输出。只有 <code>components yaml ...</code> 才输出结构化 YAML；YAML 只基于可稳定解析的原版组件字符串生成，不把 <code>String.valueOf(DataComponentValue)</code> 当作持久化格式。命令参数可省略 <code>minecraft:</code>，YAML 导出也会对原版组件使用短 ID；显式的其他命名空间保持不变。组件 ID 行支持点击复制，适合排查 1.21+ 物品组件，例如：</p><ul><li><code>minecraft:custom_model_data</code></li><li><code>minecraft:item_model</code></li><li><code>minecraft:tooltip_style</code></li><li><code>minecraft:enchantments</code></li><li><code>minecraft:attribute_modifiers</code></li></ul><p>如果省略玩家名且命令发送者是玩家，则检查自己的主手物品。如果第二个参数不是在线玩家名，会被当作组件 ID。</p><h3 id="刷新物品与套装" tabindex="-1">刷新物品与套装 <a class="header-anchor" href="#刷新物品与套装" aria-label="Permalink to &quot;刷新物品与套装&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei update</span></span>
<span class="line"><span>/ei update Steve</span></span></code></pre></div><p>修改物品定义、套装定义、自动更新规则或装备状态后使用。命令会刷新玩家背包中的 EmakiItem 物品，并重新计算已装备套装；若有变化，会触发 Attribute 装备同步。</p><h3 id="打开修复界面" tabindex="-1">打开修复界面 <a class="header-anchor" href="#打开修复界面" aria-label="Permalink to &quot;打开修复界面&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei repair</span></span></code></pre></div><p>只能由玩家执行，为自己打开 <code>gui/repair_gui.yml</code> 定义的修复界面。模板缺失时会提示打开失败。</p><h3 id="管理-id-alias" tabindex="-1">管理 ID alias <a class="header-anchor" href="#管理-id-alias" aria-label="Permalink to &quot;管理 ID alias&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei alias list</span></span>
<span class="line"><span>/ei alias add old_sword flame_sword</span></span>
<span class="line"><span>/ei alias remove old_sword</span></span></code></pre></div><p><code>add</code> 要求目标物品 ID 已加载，否则报告物品不存在。alias 变更会写回 <code>id_aliases.yml</code> 并清理物品工厂缓存。</p><h3 id="迁移物品-id-与背包" tabindex="-1">迁移物品 ID 与背包 <a class="header-anchor" href="#迁移物品-id-与背包" aria-label="Permalink to &quot;迁移物品 ID 与背包&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei migrate id old_sword flame_sword --dry-run</span></span>
<span class="line"><span>/ei migrate id old_sword flame_sword --apply</span></span>
<span class="line"><span>/ei migrate inventory Steve</span></span>
<span class="line"><span>/ei migrate inventory all</span></span></code></pre></div><p><code>migrate id</code> 必须显式带 <code>--dry-run</code> 或 <code>--apply</code>：<code>--dry-run</code> 只输出替换数量与涉及文件，<code>--apply</code> 执行替换并保留 alias。<code>migrate inventory</code> 重写目标玩家（或全部在线玩家）背包中的旧 ID，并顺带刷新套装与 Attribute 装备同步。</p><h3 id="重载配置" tabindex="-1">重载配置 <a class="header-anchor" href="#重载配置" aria-label="Permalink to &quot;重载配置&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei reload</span></span></code></pre></div><p>重载后会重新读取物品、套装、配置和语言。正式服建议先在测试服确认新配置能加载，再对在线玩家执行必要的 <code>/ei update</code>。</p><h3 id="查看刷新统计" tabindex="-1">查看刷新统计 <a class="header-anchor" href="#查看刷新统计" aria-label="Permalink to &quot;查看刷新统计&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ei debug stats</span></span></code></pre></div><p>输出物品/套装刷新的事件数、批次数、合并次数、请求与实际刷新范围、缓存命中、扫描槽位数、变更数、冲突数和耗时。可用调试模块为 <code>create</code>、<code>update</code>、<code>identify</code>、<code>set</code>、<code>item_operation</code>、<code>pdc</code>。</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to &quot;排查建议&quot;">​</a></h2><ul><li>物品列表没有目标 ID：检查 <code>items/*.yml</code> 文件名、<code>id</code>、YAML 缩进和控制台加载错误。</li><li>发放后属性不生效：用 <code>/ei inspect</code> 查看 <code>attributes</code> 与 <code>attribute_meta</code>，再确认 EmakiAttribute 是否安装。</li><li>套装不触发：用 <code>/ei inspect</code> 查看 <code>set_id</code>、<code>set_piece</code>、<code>set_active_count</code> 和 <code>set_active_thresholds</code>。</li><li>组件显示异常：用 <code>/ei components</code> 查看实际 Bukkit 组件，再回到物品定义的 <code>item.components</code> 节点修正。</li><li>更新后旧物品没变化：确认物品定义中的 <code>update.enabled</code>、<code>update.version</code> 和触发器配置，然后执行 <code>/ei update &lt;player&gt;</code>。</li></ul>`,44)])])}const u=t(o,[["render",s]]);export{h as __pageData,u as default};
